/* Feste Übersetzung der Lerninhalte (fa), maschinell erstellt, nicht von Muttersprachlern geprüft. Code bleibt unverändert. */
(function(r){"use strict";const f=r.SDAkademieFest=r.SDAkademieFest||{};(f["fa"]=f["fa"]||{})["python-start"]={"Dein erstes Python-Programm":"اولین برنامهٔ پایتون شما","Du lässt Python Text ausgeben und verstehst, wie ein Programm Zeile für Zeile abläuft.":"شما کاری می‌کنید که پایتون متن نشان دهد و می‌فهمید که یک برنامه چطور خط به خط اجرا می‌شود.","In dieser Lektion schreibst du dein erstes Programm und siehst sofort, was der Computer daraus macht.":"در این درس اولین برنامهٔ خود را می‌نویسید و فوراً می‌بینید که کمپیوتر با آن چه می‌کند.","Was ist Python?":"پایتون چیست؟","Python ist eine Programmiersprache, die sich fast wie einfaches Englisch liest. Sie wird für Webseiten, Datenanalyse, Spiele und vor allem für künstliche Intelligenz genutzt. Viele Universitäten beginnen ihre Informatik-Kurse mit Python.":"پایتون یک زبان برنامه‌نویسی است که تقریباً مثل انگلیسی ساده خوانده می‌شود. از آن برای ویب‌سایت‌ها، تحلیل داده، بازی‌ها و به‌خصوص برای هوش مصنوعی استفاده می‌شود. بسیاری از پوهنتون‌ها کورس‌های کمپیوترساینس خود را با پایتون شروع می‌کنند.","`print` ist ein Befehl, der Text auf dem Bildschirm zeigt. Der Text steht in Anführungszeichen in runden Klammern.":"`print` دستوری است که متن را روی صفحه نشان می‌دهد. متن داخل علامهٔ نقل‌قول و داخل قوس‌های گرد نوشته می‌شود.","Zeile für Zeile":"خط به خط","Der Computer liest dein Programm von oben nach unten. Jede Zeile ist ein Auftrag, der nacheinander erledigt wird. Wenn du die Reihenfolge änderst, ändert sich auch die Ausgabe.":"کمپیوتر برنامهٔ شما را از بالا به پایین می‌خواند. هر خط یک کار است که به ترتیب انجام می‌شود. اگر ترتیب را تغییر دهید، خروجی هم تغییر می‌کند.","Zuerst erscheint die erste Zeile, danach die zweite. Jeder `print`-Befehl beginnt eine neue Zeile.":"اول خط اول نمایش داده می‌شود و بعد خط دوم. هر دستور `print` یک خط تازه شروع می‌کند.","Kommentare für Menschen":"تبصره‌ها برای انسان‌ها","Mit einer Raute `#` schreibst du Notizen in den Code. Python überspringt alles hinter der Raute. So erklärst du später dir selbst oder anderen, was ein Abschnitt tut.":"با علامهٔ `#` یادداشت‌هایی در کد می‌نویسید. پایتون هر چیزی را که بعد از این علامه است نادیده می‌گیرد. به این ترتیب بعداً برای خود یا دیگران توضیح می‌دهید که یک بخش چه کار می‌کند.","Die erste Zeile ist ein Kommentar und erzeugt keine Ausgabe.":"خط اول یک تبصره است و هیچ خروجی ندارد.","Ausführen und Fehlermeldungen lesen":"اجرا کردن و خواندن پیام‌های خطا","Mit dem Knopf „Ausführen“ startet Python dein Programm direkt hier im Browser, ganz ohne Installation. Läuft etwas schief, zeigt Python eine Fehlermeldung mit der Zeilennummer. Lies die letzte Zeile der Meldung zuerst, denn dort steht die eigentliche Ursache. Fehler sind beim Programmieren völlig normal und gehören zum Lernen dazu.":"با دکمهٔ «اجرا» پایتون برنامهٔ شما را مستقیم همین‌جا در براوزر اجرا می‌کند، بدون هیچ نصبی. اگر چیزی اشتباه شود، پایتون یک پیام خطا با شمارهٔ خط نشان می‌دهد. اول خط آخر پیام را بخوانید، چون علت اصلی همان‌جا نوشته شده است. خطاها در برنامه‌نویسی کاملاً عادی هستند و بخشی از یادگیری‌اند.","Hier fehlt die schließende Klammer. Python nennt genau dieses Problem.":"اینجا قوس بسته کم است. پایتون دقیقاً همین مشکل را نام می‌برد.","Anführungszeichen vergessen":"فراموش کردن علامهٔ نقل‌قول","`print(Hallo)` sucht nach etwas namens Hallo und meldet einen Fehler. Richtig ist `print(\"Hallo\")`.":"`print(Hallo)` دنبال چیزی به نام Hallo می‌گردد و خطا می‌دهد. درستش `print(\"Hallo\")` است.","Großbuchstaben":"حروف بزرگ","`Print(\"Hi\")` funktioniert nicht, weil Python Groß- und Kleinschreibung unterscheidet. Schreibe `print` immer klein.":"`Print(\"Hi\")` کار نمی‌کند، چون پایتون بین حروف بزرگ و کوچک فرق می‌گذارد. `print` را همیشه با حروف کوچک بنویسید.","Lass Python zwei Zeilen ausgeben: zuerst „Hallo Welt“ und darunter deinen Namen.":"کاری کنید که پایتون دو خط نشان دهد: اول „Hallo Welt“ و زیر آن نام خودتان.","Schreibe zwei Zeilen, die beide mit print( beginnen.":"دو خط بنویسید که هر دو با print( شروع شوند.","Du benutzt print":"از print استفاده می‌کنید","Es gibt mindestens zwei print-Befehle":"دست‌کم دو دستور print وجود دارد","„Hallo Welt“ steht im Code":"„Hallo Welt“ در کد نوشته شده است","Was macht `print(\"Hi\")`?":"`print(\"Hi\")` چه کار می‌کند؟","Es zeigt Hi an.":"کلمهٔ Hi را نشان می‌دهد.","Es druckt ein Blatt Papier.":"یک ورق کاغذ چاپ می‌کند.","Es löscht den Bildschirm.":"صفحه را پاک می‌کند.","print gibt Text auf dem Bildschirm aus.":"print متن را روی صفحه نشان می‌دهد.","Trotz des Namens druckt print nichts auf Papier.":"با وجود نامش، print چیزی روی کاغذ چاپ نمی‌کند.","Zum Löschen gibt es keinen solchen Befehl.":"برای پاک کردن چنین دستوری وجود ندارد.","In welcher Reihenfolge führt Python Zeilen aus?":"پایتون خط‌ها را به چه ترتیبی اجرا می‌کند؟","Zufällig":"به‌طور تصادفی","Von oben nach unten":"از بالا به پایین","Von unten nach oben":"از پایین به بالا","Python arbeitet die Zeilen der Reihe nach ab.":"پایتون خط‌ها را به ترتیب یکی پس از دیگری اجرا می‌کند.","Wofür steht `#` in Python?":"علامهٔ `#` در پایتون برای چیست؟","Für eine Zahl":"برای یک عدد","Für eine Rechnung":"برای یک حساب","Für einen Kommentar":"برای یک تبصره","Hinter # steht eine Notiz, die Python überspringt.":"بعد از # یک یادداشت می‌آید که پایتون از آن می‌گذرد.","Text steht in Anführungszeichen, Befehle wie `print` nicht.":"متن داخل علامهٔ نقل‌قول است، اما دستورها مثل `print` نه.","Ein Kommentar mit `#` hilft Menschen, nicht dem Computer.":"تبصره با `#` به انسان‌ها کمک می‌کند، نه به کمپیوتر.","Python-Tutorial: Eine informelle Einführung":"آموزش پایتون: یک معرفی غیررسمی","Harvard CS50P – Python (Videos, kostenlos)":"Harvard CS50P – پایتون (ویدیوها، رایگان)","englisch, Untertitel":"انگلیسی، با زیرنویس","Variablen und Rechnen":"متغیرها و حساب کردن","Du speicherst Werte in Variablen und rechnest mit Zahlen.":"شما مقدارها را در متغیرها نگه می‌دارید و با عددها حساب می‌کنید.","Du lernst, wie Programme sich Werte merken und damit rechnen – die Grundlage für jede Anwendung.":"یاد می‌گیرید که برنامه‌ها چطور مقدارها را به یاد می‌سپارند و با آن‌ها حساب می‌کنند؛ پایهٔ هر برنامه.","Eine Variable ist eine beschriftete Kiste":"متغیر یک قطی برچسب‌دار است","Stell dir eine Kiste mit einem Etikett vor. Du legst etwas hinein und findest es später über den Namen wieder. In Python entsteht eine Variable, sobald du ihr mit dem Gleichheitszeichen einen Wert gibst.":"یک قطی با یک برچسب را تصور کنید. چیزی داخلش می‌گذارید و بعداً با نامش دوباره پیدایش می‌کنید. در پایتون یک متغیر همین که با علامهٔ مساوی به آن مقدار بدهید ساخته می‌شود.","`alter` enthält die Zahl 25, `name` enthält Text. Beim Ausgeben schreibst du den Namen ohne Anführungszeichen.":"`alter` عدد 25 را دارد و `name` یک متن را. هنگام نمایش، نام را بدون علامهٔ نقل‌قول می‌نویسید.","Rechnen wie mit dem Taschenrechner":"حساب کردن مثل ماشین‌حساب","Python kennt Plus, Minus, Mal mit Stern und Geteilt mit Schrägstrich. Klammern bestimmen, was zuerst gerechnet wird. Das Ergebnis kannst du direkt ausgeben oder in einer neuen Variable speichern.":"پایتون جمع، تفریق، ضرب با ستاره و تقسیم با خط مایل را می‌شناسد. قوس‌ها تعیین می‌کنند که اول کدام حساب شود. نتیجه را می‌توانید مستقیم نشان دهید یا در یک متغیر تازه نگه دارید.","Hier wird 4 mal 3 gerechnet, also erscheint 12.":"اینجا 4 ضرب 3 حساب می‌شود، پس 12 نمایش داده می‌شود.","Text und Zahlen zusammen ausgeben":"نمایش متن و عدد با هم","Mit einem f-String setzt du Variablen direkt in einen Satz ein. Dafür steht ein f vor den Anführungszeichen. Die Variable kommt in geschweifte Klammern.":"با یک f-String متغیرها را مستقیم داخل یک جمله می‌گذارید. برای این کار یک f قبل از علامهٔ نقل‌قول می‌آید. متغیر داخل قوس‌های گُل‌دار نوشته می‌شود.","Python ersetzt `{stunden}` durch den Wert 8.":"پایتون `{stunden}` را با مقدار 8 عوض می‌کند.","Werte ändern sich":"مقدارها تغییر می‌کنند","Eine Variable kann im Laufe des Programms einen neuen Wert bekommen. Rechts vom Gleichheitszeichen darf dabei auch die Variable selbst stehen. So zählt ein Programm etwa Punkte in einem Spiel hoch oder zieht Geld vom Kontostand ab. Die Kurzform `punkte += 5` bedeutet dasselbe wie `punkte = punkte + 5`.":"یک متغیر در جریان برنامه می‌تواند مقدار تازه بگیرد. در طرف راست علامهٔ مساوی خود همان متغیر هم می‌تواند باشد. به این ترتیب یک برنامه مثلاً امتیازهای یک بازی را بالا می‌برد یا پول را از موجودی حساب کم می‌کند. شکل کوتاه `punkte += 5` همان معنای `punkte = punkte + 5` را دارد.","Nach beiden Abzügen bleiben 50 übrig.":"بعد از هر دو کسر، 50 باقی می‌ماند.","Leerzeichen im Namen":"فاصله در نام","`mein alter = 5` geht nicht. Verwende einen Unterstrich: `mein_alter = 5`.":"`mein alter = 5` کار نمی‌کند. از خط زیرین استفاده کنید: `mein_alter = 5`.","Text statt Zahl":"متن به جای عدد","`\"3\" + \"4\"` ergibt 34, weil Texte aneinandergehängt werden. Für die Summe schreibst du `3 + 4` ohne Anführungszeichen.":"`\"3\" + \"4\"` نتیجهٔ 34 می‌دهد، چون متن‌ها به هم چسپانده می‌شوند. برای مجموع، `3 + 4` را بدون علامهٔ نقل‌قول بنویسید.","Berechne den Gesamtpreis für Brot und Milch, speichere ihn in `summe` und gib mit einem f-String aus: „Summe: 3.7 Euro“.":"قیمت مجموعی نان و شیر را حساب کنید، آن را در `summe` نگه دارید و با یک f-String نشان دهید: „Summe: 3.7 Euro“.","summe = brot + milch und dann print(f\"Summe: {summe} Euro\")":"summe = brot + milch و بعد print(f\"Summe: {summe} Euro\")","Es gibt eine Variable summe":"یک متغیر به نام summe وجود دارد","Du addierst mit +":"با + جمع می‌کنید","Du benutzt einen f-String":"از یک f-String استفاده می‌کنید","Was speichert `x = 10`?":"`x = 10` چه چیزی را نگه می‌دارد؟","Den Text x":"متن x را","Die Zahl 10 unter dem Namen x":"عدد 10 را زیر نام x","Eine Frage":"یک سوال را","Das Gleichheitszeichen legt den Wert 10 in die Variable x.":"علامهٔ مساوی مقدار 10 را در متغیر x می‌گذارد.","Welches Zeichen bedeutet „mal“?":"کدام علامه معنای «ضرب» دارد؟","Der Stern ist in Python das Malzeichen.":"ستاره در پایتون علامهٔ ضرب است.","Wie setzt du eine Variable in einen Text ein?":"یک متغیر را چطور داخل یک متن می‌گذارید؟","Mit einem f-String und {name}":"با یک f-String و {name}","Mit print ohne Klammern":"با print بدون قوس","Mit einem Kommentar":"با یک تبصره","Ein f-String ersetzt geschweifte Klammern durch Werte.":"یک f-String قوس‌های گُل‌دار را با مقدارها عوض می‌کند.","Variablennamen schreibst du klein und mit Unterstrich statt Leerzeichen.":"نام متغیرها را با حروف کوچک و با خط زیرین به جای فاصله بنویسید.","Zahlen ohne Anführungszeichen kann man berechnen, Texte nicht.":"با عددهای بدون علامهٔ نقل‌قول می‌شود حساب کرد، با متن نه.","Python-Tutorial: Python als Taschenrechner":"آموزش پایتون: پایتون به عنوان ماشین‌حساب","Universität Helsinki – Python Programming MOOC 2026":"پوهنتون هلسینکی – Python Programming MOOC 2026","englisch, kostenlos":"انگلیسی، رایگان","Eingaben vom Nutzer":"ورودی از کاربر","Dein Programm fragt etwas und reagiert auf die Antwort.":"برنامهٔ شما چیزی می‌پرسد و به جواب واکنش نشان می‌دهد.","Hier lernst du, wie dein Programm mit Menschen spricht: Es stellt Fragen und verarbeitet die Antworten.":"اینجا یاد می‌گیرید که برنامهٔ شما چطور با انسان‌ها حرف می‌زند: سوال می‌پرسد و جواب‌ها را پردازش می‌کند.","Fragen mit input()":"پرسیدن با input()","Mit `input()` wartet dein Programm, bis jemand etwas eintippt. In die Klammern schreibst du die Frage. Die Antwort speicherst du in einer Variable.":"با `input()` برنامهٔ شما صبر می‌کند تا کسی چیزی تایپ کند. سوال را داخل قوس‌ها می‌نویسید. جواب را در یک متغیر نگه می‌دارید.","Unten im Feld „Eingaben“ steht, was das Programm als Antwort bekommt.":"در خانهٔ «ورودی‌ها» در پایین نوشته است که برنامه چه جوابی می‌گیرد.","Antworten sind immer Text":"جواب‌ها همیشه متن هستند","Alles, was eingetippt wird, kommt als Text an, auch Ziffern. Zum Rechnen wandelst du den Text mit `int()` in eine ganze Zahl um. Für Kommazahlen gibt es `float()`.":"هر چیزی که تایپ شود به شکل متن می‌رسد، حتی رقم‌ها. برای حساب کردن، متن را با `int()` به یک عدد صحیح تبدیل می‌کنید. برای عددهای اعشاری `float()` وجود دارد.","`int()` macht aus dem Text „2000“ die Zahl 2000, mit der man rechnen kann.":"`int()` از متن „2000“ عدد 2000 را می‌سازد که با آن می‌شود حساب کرد.","Mehrere Fragen nacheinander":"چند سوال پشت سر هم","Du kannst beliebig viele Fragen hintereinander stellen. Jede Eingabezeile im Feld gehört zu einem `input()`. So entstehen kleine Rechner und Formulare.":"می‌توانید هر قدر سوال بخواهید پشت سر هم بپرسید. هر خط ورودی در خانه به یک `input()` تعلق دارد. به این ترتیب ماشین‌حساب‌ها و فورم‌های کوچک ساخته می‌شوند.","Die erste Eingabezeile landet in a, die zweite in b.":"خط اول ورودی در a می‌رود و خط دوم در b.","Kommazahlen einlesen":"خواندن عددهای اعشاری","Für Preise, Gewichte oder Temperaturen brauchst du Kommazahlen. Dafür wandelst du die Eingabe mit `float()` um. Achtung: Python erwartet einen Punkt statt eines Kommas, also 2.5 und nicht 2,5. Erkläre das in deiner Frage, damit niemand sich wundert. Schreibe die Frage immer so, dass klar ist, welche Art von Antwort erwartet wird, zum Beispiel mit einer Einheit wie Euro oder Meter.":"برای قیمت‌ها، وزن‌ها یا درجهٔ حرارت به عددهای اعشاری نیاز دارید. برای این کار ورودی را با `float()` تبدیل می‌کنید. توجه: پایتون به جای کامه یک نقطه می‌خواهد، یعنی 2.5 و نه 2,5. این را در سوال خود توضیح دهید تا کسی تعجب نکند. سوال را همیشه طوری بنویسید که روشن باشد چه نوع جوابی انتظار می‌رود، مثلاً با یک واحد مثل یورو یا متر.","Bei der Eingabe 2.5 erscheint 5.0.":"با ورودی 2.5 عدد 5.0 نمایش داده می‌شود.","Rechnen mit Text":"حساب کردن با متن","`input(\"Zahl? \") + 5` meldet einen Fehler. Wandle zuerst um: `int(input(\"Zahl? \")) + 5`.":"`input(\"Zahl? \") + 5` خطا می‌دهد. اول تبدیل کنید: `int(input(\"Zahl? \")) + 5`.","Keine Eingabe vorbereitet":"هیچ ورودی آماده نشده","Wenn das Eingabefeld leer ist, bekommt input() nichts und das Programm bricht ab. Trage vorher eine Zeile pro Frage ein.":"اگر خانهٔ ورودی خالی باشد، input() چیزی نمی‌گیرد و برنامه متوقف می‌شود. از قبل برای هر سوال یک خط بنویسید.","Frage nach der Breite und der Länge eines Zimmers (ganze Zahlen) und gib die Fläche aus, z. B. „Fläche: 12“. Im Eingabefeld stehen schon 3 und 4.":"عرض و طول یک اتاق (عددهای صحیح) را بپرسید و مساحت را نشان دهید، مثلاً „Fläche: 12“. در خانهٔ ورودی از قبل 3 و 4 نوشته شده است.","breite = int(input(\"Breite? \")), dasselbe für die Länge, dann print(f\"Fläche: {breite * laenge}\")":"breite = int(input(\"Breite? \"))، همین کار را برای طول کنید، بعد print(f\"Fläche: {breite * laenge}\")","Du benutzt input zweimal":"دو بار از input استفاده می‌کنید","Du wandelst mit int um":"با int تبدیل می‌کنید","Du multiplizierst":"ضرب می‌کنید","Welchen Typ hat das Ergebnis von `input()`?":"نتیجهٔ `input()` چه نوعی دارد؟","Zahl":"عدد","Liste":"لست","Text":"متن","input liefert immer Text, auch bei Ziffern.":"input همیشه متن می‌دهد، حتی برای رقم‌ها.","Wie wird aus dem Text \"7\" die Zahl 7?":"متن \"7\" چطور به عدد 7 تبدیل می‌شود؟","int wandelt Text in eine ganze Zahl um.":"int متن را به یک عدد صحیح تبدیل می‌کند.","Was passiert bei zwei input()-Befehlen?":"با دو دستور input() چه اتفاقی می‌افتد؟","Python fragt nur einmal.":"پایتون فقط یک بار می‌پرسد.","Python fragt zweimal nacheinander.":"پایتون دو بار پشت سر هم می‌پرسد.","Beide bekommen dieselbe Antwort.":"هر دو یک جواب را می‌گیرند.","Jedes input wartet auf seine eigene Antwort.":"هر input منتظر جواب خودش می‌ماند.","Eingaben sind Text, zum Rechnen brauchst du `int()` oder `float()`.":"ورودی‌ها متن هستند؛ برای حساب کردن به `int()` یا `float()` نیاز دارید.","Eine gute Frage im input() erklärt, was eingetippt werden soll.":"یک سوال خوب در input() توضیح می‌دهد که چه چیزی باید تایپ شود.","Python-Doku: Eingebaute Funktion input()":"مستندات پایتون: تابع داخلی input()","openHPI – Python für Einsteiger (deutsch, kostenlos)":"openHPI – پایتون برای مبتدیان (به زبان آلمانی، رایگان)","Entscheidungen mit if":"تصمیم‌گیری با if","Dein Programm trifft Entscheidungen abhängig von Werten.":"برنامهٔ شما بسته به مقدارها تصمیم می‌گیرد.","Programme werden erst richtig nützlich, wenn sie je nach Lage unterschiedlich reagieren – genau das lernst du hier.":"برنامه‌ها وقتی واقعاً مفید می‌شوند که بسته به وضعیت واکنش‌های مختلف نشان دهند؛ دقیقاً همین را اینجا یاد می‌گیرید.","Wenn – dann":"اگر – پس","Mit `if` prüfst du eine Bedingung. Ist sie wahr, führt Python die eingerückten Zeilen darunter aus. Die Einrückung mit vier Leerzeichen zeigt, was zur Bedingung gehört.":"با `if` یک شرط را بررسی می‌کنید. اگر درست باشد، پایتون خط‌های تورفته زیر آن را اجرا می‌کند. تورفتگی با چهار فاصله نشان می‌دهد که چه چیزی به شرط تعلق دارد.","Weil 30 größer als 25 ist, erscheint der Satz.":"چون 30 از 25 بزرگ‌تر است، جمله نمایش داده می‌شود.","Sonst mit else und elif":"در غیر آن صورت با else و elif","Mit `else` legst du fest, was passiert, wenn die Bedingung nicht stimmt. `elif` prüft eine weitere Bedingung dazwischen. Python nimmt immer nur den ersten passenden Zweig.":"با `else` تعیین می‌کنید که اگر شرط درست نباشد چه شود. `elif` در این میان یک شرط دیگر را بررسی می‌کند. پایتون همیشه فقط اولین شاخهٔ مناسب را انتخاب می‌کند.","Zwei Gleichheitszeichen vergleichen. Hier passt der elif-Zweig.":"دو علامهٔ مساوی مقایسه می‌کنند. اینجا شاخهٔ elif مناسب است.","Vergleiche verbinden":"وصل کردن مقایسه‌ها","Mit `and` müssen beide Bedingungen stimmen, mit `or` reicht eine. So baust du Regeln wie bei einer Eintrittskasse. Mit `not` drehst du eine Bedingung um.":"با `and` هر دو شرط باید درست باشند و با `or` یکی کافی است. به این ترتیب قاعده‌هایی مثل قاعده‌های یک گیشهٔ ورودی می‌سازید. با `not` یک شرط را برعکس می‌کنید.","Eine der beiden Bedingungen ist wahr, also ist der Eintritt erlaubt.":"یکی از دو شرط درست است، پس ورود اجازه دارد.","Bedingungen im Alltag":"شرط‌ها در زندگی روزمره","Viele alltägliche Regeln lassen sich als if-Abfrage schreiben: Rabatt ab einem Einkaufswert, Warnung bei niedrigem Akku oder Mahnung nach einer Frist. Formuliere die Regel zuerst als deutschen Satz mit „wenn … dann … sonst“. Danach übersetzt du sie Wort für Wort in Python. Teste anschließend Werte knapp über und unter der Grenze. Diese Grenzfälle sind die häufigste Quelle für Fehler in echten Programmen.":"بسیاری از قاعده‌های روزمره را می‌شود به شکل یک if نوشت: تخفیف از یک مبلغ خرید به بالا، هشدار وقتی باتری کم است یا یادآوری بعد از یک مهلت. اول قاعده را به شکل یک جمله با «اگر … پس … در غیر آن» بنویسید. بعد آن را کلمه به کلمه به پایتون برگردانید. سپس مقدارهایی را کمی بالاتر و کمی پایین‌تر از حد آزمایش کنید. این حالت‌های مرزی شایع‌ترین منبع خطا در برنامه‌های واقعی هستند.","Teste mit 49, 50 und 51, um die Grenze sicher zu prüfen.":"با 49، 50 و 51 آزمایش کنید تا حد را با اطمینان بررسی کنید.","Doppelpunkt fehlt":"دونقطه کم است","`if x > 3` ohne Doppelpunkt ist ein Syntaxfehler. Richtig: `if x > 3:`.":"`if x > 3` بدون دونقطه یک خطای نحوی است. درستش: `if x > 3:`.","Ein statt zwei Gleichheitszeichen":"یک علامهٔ مساوی به جای دو","`if x = 5:` ist falsch, weil = etwas speichert. Zum Vergleichen schreibst du `==`.":"`if x = 5:` اشتباه است، چون = چیزی را نگه می‌دارد. برای مقایسه `==` بنویسید.","Prüfe die Variable punkte: Ab 50 Punkten soll „bestanden“ erscheinen, sonst „nicht bestanden“.":"متغیر punkte را بررسی کنید: از 50 امتیاز به بالا باید „bestanden“ نمایش داده شود، در غیر آن „nicht bestanden“.","if punkte >= 50: und eingerückt print(\"bestanden\"), darunter else:":"if punkte >= 50: و تورفته print(\"bestanden\")، زیر آن else:","Du benutzt if":"از if استفاده می‌کنید","Du benutzt else":"از else استفاده می‌کنید","Du vergleichst mit 50":"با 50 مقایسه می‌کنید","Was zeigt die Einrückung unter if?":"تورفتگی زیر if چه چیزی را نشان می‌دهد؟","Welche Zeilen zur Bedingung gehören":"کدام خط‌ها به شرط تعلق دارند","Nur die Schönheit des Codes":"فقط زیبایی کد را","Dass die Zeile ein Kommentar ist":"اینکه آن خط یک تبصره است","Eingerückte Zeilen werden nur ausgeführt, wenn die Bedingung stimmt.":"خط‌های تورفته فقط وقتی اجرا می‌شوند که شرط درست باشد.","Welcher Operator vergleicht auf Gleichheit?":"کدام عملگر برابری را مقایسه می‌کند؟","== vergleicht, = speichert einen Wert.":"== مقایسه می‌کند، = یک مقدار را نگه می‌دارد.","Wann ist `a or b` wahr?":"`a or b` چه وقت درست است؟","Nur wenn beide wahr sind":"فقط وقتی هر دو درست باشند","Wenn mindestens eines wahr ist":"وقتی دست‌کم یکی درست باشد","Nie":"هرگز","or braucht nur eine wahre Seite.":"or فقط به یک طرف درست نیاز دارد.","Nach `if`, `elif` und `else` kommt immer ein Doppelpunkt.":"بعد از `if`، `elif` و `else` همیشه یک دونقطه می‌آید.","Vier Leerzeichen Einrückung gehören in Python zur Logik.":"تورفتگی با چهار فاصله در پایتون بخشی از منطق برنامه است.","Python-Tutorial: if-Anweisungen":"آموزش پایتون: دستورهای if","Wiederholen mit Schleifen":"تکرار با حلقه‌ها","Du lässt Python Aufgaben automatisch wiederholen.":"کاری می‌کنید که پایتون کارها را خودکار تکرار کند.","Schleifen nehmen dir wiederholte Arbeit ab – egal ob zehnmal oder eine Million Mal.":"حلقه‌ها کار تکراری را از دوش شما برمی‌دارند؛ چه ده بار باشد چه یک میلیون بار.","for zählt für dich":"for برای شما می‌شمارد","Eine `for`-Schleife wiederholt Zeilen für jeden Wert einer Reihe. `range(5)` erzeugt die Zahlen 0 bis 4. So musst du nicht fünfmal dasselbe schreiben.":"یک حلقهٔ `for` خط‌ها را برای هر مقدار یک رشته تکرار می‌کند. `range(5)` عددهای 0 تا 4 را می‌سازد. به این ترتیب لازم نیست یک چیز را پنج بار بنویسید.","Die Schleife läuft dreimal mit i gleich 0, 1 und 2.":"حلقه سه بار اجرا می‌شود، با i برابر 0، 1 و 2.","Eigener Start und Schritt":"شروع و گام دلخواه","`range(1, 11)` zählt von 1 bis 10, denn das Ende gehört nicht dazu. Mit einer dritten Zahl bestimmst du die Schrittweite. Damit lassen sich Einmaleins-Tabellen schnell bauen.":"`range(1, 11)` از 1 تا 10 می‌شمارد، چون عدد پایانی شامل نمی‌شود. با یک عدد سوم اندازهٔ گام را تعیین می‌کنید. با این کار جدول‌های ضرب را به‌سرعت می‌سازید.","Ausgegeben werden 2, 4, 6, 8 und 10.":"عددهای 2، 4، 6، 8 و 10 نمایش داده می‌شوند.","while wiederholt, solange etwas stimmt":"while تا وقتی چیزی درست باشد تکرار می‌کند","Eine `while`-Schleife läuft, bis ihre Bedingung falsch wird. Du musst darin etwas verändern, sonst läuft sie endlos. Ein Countdown ist ein typisches Beispiel.":"یک حلقهٔ `while` تا وقتی اجرا می‌شود که شرطش نادرست شود. باید داخل آن چیزی را تغییر دهید، وگرنه بی‌پایان ادامه می‌یابد. یک شمارش معکوس مثال معمول آن است.","Jede Runde verringert sekunden um eins, bei 0 endet die Schleife.":"هر دور sekunden را یکی کم می‌کند و با رسیدن به 0 حلقه تمام می‌شود.","Schleifen mit Bedingungen kombinieren":"ترکیب حلقه‌ها با شرط‌ها","Innerhalb einer Schleife darfst du alle bisherigen Werkzeuge benutzen, auch if-Abfragen. So zählst du etwa nur bestimmte Werte oder überspringst manche Runden. Mit `break` verlässt du eine Schleife vorzeitig, sobald du gefunden hast, was du suchst. Das spart Rechenzeit bei großen Datenmengen. Gerade bei langen Listen merkt man schnell, wie viel Zeit das spart.":"داخل یک حلقه می‌توانید از همهٔ ابزارهایی که تا حالا یاد گرفته‌اید استفاده کنید، از جمله if. به این ترتیب مثلاً فقط مقدارهای معینی را می‌شمارید یا از بعضی دورها می‌گذرید. با `break` همین که آنچه را می‌خواستید پیدا کردید، حلقه را زودتر ترک می‌کنید. این کار در داده‌های زیاد وقت محاسبه را صرفه‌جویی می‌کند. مخصوصاً در لست‌های طولانی زود معلوم می‌شود که چقدر وقت صرفه‌جویی می‌شود.","Die Schleife endet bei 7, weil break sie verlässt.":"حلقه در 7 تمام می‌شود، چون break آن را ترک می‌کند.","Endlosschleife":"حلقهٔ بی‌پایان","Wenn sich in `while` nichts ändert, hört sie nie auf. Verändere die geprüfte Variable in jeder Runde.":"اگر در `while` چیزی تغییر نکند، هرگز تمام نمی‌شود. متغیری را که بررسی می‌شود در هر دور تغییر دهید.","range endet zu früh":"range زود تمام می‌شود","`range(1, 10)` endet bei 9. Für 1 bis 10 schreibst du `range(1, 11)`.":"`range(1, 10)` در 9 تمام می‌شود. برای 1 تا 10، `range(1, 11)` بنویسید.","Gib mit einer for-Schleife das Siebener-Einmaleins aus: „7 x 1 = 7“ bis „7 x 10 = 70“.":"با یک حلقهٔ for جدول ضرب هفت را نشان دهید: از „7 x 1 = 7“ تا „7 x 10 = 70“.","for i in range(1, 11): und darin print(f\"7 x {i} = {7 * i}\")":"for i in range(1, 11): و داخل آن print(f\"7 x {i} = {7 * i}\")","Du benutzt for":"از for استفاده می‌کنید","Du benutzt range":"از range استفاده می‌کنید","Du multiplizierst mit 7":"با 7 ضرب می‌کنید","Welche Zahlen erzeugt `range(3)`?":"`range(3)` کدام عددها را می‌سازد؟","range beginnt bei 0 und endet vor der angegebenen Zahl.":"range از 0 شروع می‌شود و پیش از عدد داده‌شده تمام می‌شود.","Was braucht jede while-Schleife?":"هر حلقهٔ while به چه چیزی نیاز دارد؟","Eine Bedingung, die irgendwann falsch wird":"شرطی که بالاخره نادرست شود","Einen Kommentar":"یک تبصره","Eine Liste":"یک لست","Sonst läuft sie endlos weiter.":"وگرنه بی‌پایان ادامه می‌یابد.","Was gibt `range(0, 10, 5)` aus?":"`range(0, 10, 5)` چه چیزی می‌دهد؟","0 bis 10":"0 تا 10","5 und 10":"5 و 10","0 und 5":"0 و 5","Mit Schritt 5 entstehen 0 und 5, die 10 gehört nicht dazu.":"با گام 5، عددهای 0 و 5 ساخته می‌شوند؛ 10 شامل نمی‌شود.","`for` nimmst du, wenn die Anzahl klar ist, `while` bei einer Bedingung.":"`for` را وقتی به کار می‌برید که تعداد معلوم باشد و `while` را برای یک شرط.","Das Ende von `range` ist nie dabei.":"عدد پایانی `range` هرگز شامل نمی‌شود.","Python-Tutorial: for und range()":"آموزش پایتون: for و range()","Listen: viele Werte in einer Variable":"لست‌ها: چند مقدار در یک متغیر","Du speicherst mehrere Werte in einer Liste und arbeitest mit ihnen.":"شما چند مقدار را در یک لست نگه می‌دارید و با آن‌ها کار می‌کنید.","Mit Listen verwaltest du viele Werte auf einmal – zum Beispiel Einkäufe, Noten oder Messwerte.":"با لست‌ها چندین مقدار را یک‌جا مدیریت می‌کنید؛ مثلاً خریدها، نمره‌ها یا اندازه‌گیری‌ها.","Eine Liste anlegen":"ساختن یک لست","Eine Liste sammelt Werte in eckigen Klammern, getrennt durch Kommas. Wie eine Einkaufsliste kann sie beliebig lang sein. Mit `len()` erfährst du, wie viele Einträge sie hat.":"یک لست مقدارها را داخل قوس‌های چهارگوش و جداشده با کامه جمع می‌کند. مثل لست خرید، می‌تواند هر قدر بخواهید طولانی باشد. با `len()` می‌فهمید که چند عنصر دارد.","Die Liste hat drei Einträge, also erscheint 3.":"لست سه عنصر دارد، پس 3 نمایش داده می‌شود.","Auf Einträge zugreifen":"دسترسی به عنصرها","Jeder Eintrag hat eine Position, die bei 0 beginnt. `obst[0]` ist also der erste Eintrag. Mit `append()` hängst du etwas hinten an.":"هر عنصر یک جایگاه دارد که از 0 شروع می‌شود. پس `obst[0]` اولین عنصر است. با `append()` چیزی را به آخر لست اضافه می‌کنید.","Ausgegeben werden Apfel und danach die ganze Liste mit Mango am Ende.":"اول Apfel نمایش داده می‌شود و بعد تمام لست با Mango در آخر.","Durch eine Liste laufen":"گشتن در یک لست","Eine for-Schleife kann jeden Eintrag einer Liste nacheinander bearbeiten. Mit `sum()` addierst du alle Zahlen einer Liste. Das ist die Grundlage vieler Auswertungen.":"یک حلقهٔ for می‌تواند هر عنصر یک لست را یکی پس از دیگری پردازش کند. با `sum()` همهٔ عددهای یک لست را جمع می‌کنید. این پایهٔ بسیاری از ارزیابی‌هاست.","Die Schleife zeigt jede Zahl, sum() rechnet 23.":"حلقه هر عدد را نشان می‌دهد و sum() نتیجهٔ 23 را حساب می‌کند.","Listen sortieren und durchsuchen":"مرتب کردن و جستجو در لست‌ها","`sorted()` liefert eine sortierte Kopie einer Liste, `in` prüft, ob ein Wert enthalten ist. Mit `max()` und `min()` findest du den größten und kleinsten Eintrag. Diese Werkzeuge ersetzen viele selbstgeschriebene Schleifen. Sie funktionieren mit Zahlen genauso wie mit Wörtern. Probiere sie zuerst mit einer kleinen Liste aus, deren Ergebnis du im Kopf kennst.":"`sorted()` یک کاپی مرتب‌شده از لست می‌دهد و `in` بررسی می‌کند که آیا یک مقدار در آن هست یا نه. با `max()` و `min()` بزرگ‌ترین و کوچک‌ترین عنصر را پیدا می‌کنید. این ابزارها جای بسیاری از حلقه‌هایی را می‌گیرند که خودتان می‌نوشتید. با عددها همان‌طور کار می‌کنند که با کلمه‌ها. اول آن‌ها را با یک لست کوچک امتحان کنید که نتیجه‌اش را در ذهن می‌دانید.","Ausgegeben werden [1, 2, 3, 4] sowie True und 4.":"[1, 2, 3, 4] و همچنین True و 4 نمایش داده می‌شوند.","Zählen ab 1":"شمردن از 1","`liste[1]` ist schon der zweite Eintrag. Der erste ist `liste[0]`.":"`liste[1]` در واقع عنصر دوم است. عنصر اول `liste[0]` است.","Position zu groß":"جایگاه بیش از حد بزرگ","Bei drei Einträgen gibt es `liste[3]` nicht und Python meldet IndexError. Der letzte Eintrag ist `liste[-1]`.":"در لستی با سه عنصر، `liste[3]` وجود ندارد و پایتون خطای IndexError می‌دهد. آخرین عنصر `liste[-1]` است.","Berechne den Durchschnitt der Liste temperaturen (Summe geteilt durch Anzahl) und gib „Durchschnitt: 21.2“ aus.":"اوسط لست temperaturen را حساب کنید (مجموع تقسیم بر تعداد) و „Durchschnitt: 21.2“ را نشان دهید.","Du benutzt sum":"از sum استفاده می‌کنید","Du benutzt len":"از len استفاده می‌کنید","Du teilst":"تقسیم می‌کنید","Welche Position hat der erste Eintrag?":"اولین عنصر کدام جایگاه را دارد؟","Python zählt Positionen ab 0.":"پایتون جایگاه‌ها را از 0 می‌شمارد.","Was macht `append(\"X\")`?":"`append(\"X\")` چه کار می‌کند؟","Löscht X":"X را پاک می‌کند","Hängt X hinten an":"X را به آخر اضافه می‌کند","Sortiert die Liste":"لست را مرتب می‌کند","append fügt am Ende hinzu.":"append در آخر اضافه می‌کند.","Was liefert `len([4, 4, 4])`?":"`len([4, 4, 4])` چه چیزی می‌دهد؟","len zählt die Einträge, nicht ihre Werte.":"len عنصرها را می‌شمارد، نه مقدار آن‌ها را.","Listen stehen in eckigen Klammern und beginnen bei Position 0.":"لست‌ها داخل قوس‌های چهارگوش هستند و از جایگاه 0 شروع می‌شوند.","`len`, `sum` und `append` brauchst du ständig.":"`len`، `sum` و `append` را همیشه لازم دارید.","Python-Tutorial: Listen":"آموزش پایتون: لست‌ها","Eigene Funktionen":"تابع‌های خودتان","Du baust wiederverwendbare Befehle mit def.":"با def دستورهایی می‌سازید که دوباره قابل استفاده‌اند.","Funktionen machen aus langen Programmen übersichtliche Bausteine, die du immer wieder verwenden kannst.":"تابع‌ها برنامه‌های طولانی را به بخش‌های روشن تبدیل می‌کنند که بارها می‌توانید از آن‌ها استفاده کنید.","Warum Funktionen?":"چرا تابع؟","Eine Funktion ist wie ein Rezept: einmal aufgeschrieben, beliebig oft benutzt. Sie bekommt einen Namen und kann Werte entgegennehmen. Das macht Programme kürzer und leichter zu ändern.":"یک تابع مثل یک دستور پخت است: یک بار نوشته می‌شود و هر قدر بخواهید استفاده می‌شود. یک نام می‌گیرد و می‌تواند مقدارهایی را دریافت کند. این کار برنامه‌ها را کوتاه‌تر و تغییرشان را آسان‌تر می‌کند.","`def` legt die Funktion an, der Aufruf mit Klammern führt sie aus.":"`def` تابع را می‌سازد و صدا زدن آن با قوس‌ها آن را اجرا می‌کند.","Parameter: Werte übergeben":"پارامترها: فرستادن مقدارها","In den Klammern stehen Parameter, also Platzhalter für Werte. Beim Aufruf setzt du echte Werte ein. So begrüßt dieselbe Funktion verschiedene Menschen.":"داخل قوس‌ها پارامترها هستند، یعنی جای‌نگهدارهایی برای مقدارها. هنگام صدا زدن، مقدارهای واقعی را می‌گذارید. به این ترتیب یک تابع به آدم‌های مختلف خوش‌آمد می‌گوید.","Beim Aufruf bekommt name den Wert Omid.":"هنگام صدا زدن، name مقدار Omid را می‌گیرد.","Ergebnisse mit return":"نتیجه‌ها با return","Mit `return` gibt eine Funktion ein Ergebnis zurück, statt es nur anzuzeigen. Das Ergebnis kannst du speichern oder weiterrechnen. Rechnende Funktionen sollten fast immer return benutzen.":"با `return` یک تابع نتیجه‌ای را پس می‌دهد، به جای اینکه فقط نشانش دهد. نتیجه را می‌توانید نگه دارید یا با آن حساب را ادامه دهید. تابع‌هایی که حساب می‌کنند تقریباً همیشه باید از return استفاده کنند.","Die Funktion rechnet 19 Prozent Mehrwertsteuer dazu und liefert 119.0.":"تابع 19 فیصد مالیات بر ارزش افزوده را اضافه می‌کند و 119.0 را پس می‌دهد.","Standardwerte für Parameter":"مقدارهای پیش‌فرض برای پارامترها","Ein Parameter kann einen Standardwert bekommen, der gilt, wenn beim Aufruf nichts angegeben wird. So bleibt eine Funktion einfach zu benutzen und trotzdem anpassbar. Parameter mit Standardwert stehen immer hinter den Pflichtparametern. Viele eingebaute Funktionen von Python arbeiten genau so.":"یک پارامتر می‌تواند یک مقدار پیش‌فرض بگیرد که وقتی هنگام صدا زدن چیزی داده نشود، به کار می‌رود. به این ترتیب استفاده از تابع ساده می‌ماند و با این حال قابل تنظیم است. پارامترهای دارای مقدار پیش‌فرض همیشه بعد از پارامترهای اجباری می‌آیند. بسیاری از تابع‌های داخلی پایتون دقیقاً همین‌طور کار می‌کنند.","Ohne zweite Angabe wird Deutsch benutzt.":"بدون مقدار دوم، آلمانی استفاده می‌شود.","Aufruf ohne Klammern":"صدا زدن بدون قوس","`begruessen` ohne Klammern führt nichts aus. Erst `begruessen()` startet die Funktion.":"`begruessen` بدون قوس چیزی را اجرا نمی‌کند. فقط `begruessen()` تابع را شروع می‌کند.","print statt return":"print به جای return","Eine Funktion mit print liefert None zurück. Wenn du mit dem Ergebnis rechnen willst, benutze `return`.":"تابعی که از print استفاده می‌کند، None پس می‌دهد. اگر می‌خواهید با نتیجه حساب کنید، از `return` استفاده کنید.","Schreibe eine Funktion `flaeche(breite, hoehe)`, die das Produkt zurückgibt, und gib `flaeche(5, 3)` aus.":"یک تابع `flaeche(breite, hoehe)` بنویسید که حاصل ضرب را پس بدهد و `flaeche(5, 3)` را نشان دهید.","Erst def flaeche(breite, hoehe): und darunter eingerückt return breite * hoehe.":"اول def flaeche(breite, hoehe): و زیر آن تورفته return breite * hoehe.","Du definierst flaeche mit zwei Parametern":"flaeche را با دو پارامتر تعریف می‌کنید","Du benutzt return":"از return استفاده می‌کنید","Du rufst flaeche(5, 3) auf":"flaeche(5, 3) را صدا می‌زنید","Mit welchem Wort beginnt eine Funktion?":"یک تابع با کدام کلمه شروع می‌شود؟","In Python definiert man Funktionen mit def.":"در پایتون تابع‌ها را با def تعریف می‌کنند.","Was bewirkt return?":"return چه کار می‌کند؟","Es beendet Python.":"پایتون را بسته می‌کند.","Es gibt einen Wert an den Aufrufer zurück.":"یک مقدار را به جایی که تابع صدا زده شده پس می‌دهد.","Es druckt Text.":"متن چاپ می‌کند.","return liefert das Ergebnis der Funktion.":"return نتیجهٔ تابع را می‌دهد.","Was ist ein Parameter?":"پارامتر چیست؟","Ein Kommentar":"یک تبصره","Eine Schleife":"یک حلقه","Ein Platzhalter für einen übergebenen Wert":"یک جای‌نگهدار برای مقداری که فرستاده می‌شود","Parameter stehen in den Klammern der Funktion.":"پارامترها داخل قوس‌های تابع نوشته می‌شوند.","Eine gute Funktion erledigt genau eine Aufgabe und hat einen sprechenden Namen.":"یک تابع خوب دقیقاً یک کار را انجام می‌دهد و نامی دارد که معنایش را بگوید.","Rechnende Funktionen geben ihr Ergebnis mit `return` zurück.":"تابع‌هایی که حساب می‌کنند نتیجهٔ خود را با `return` پس می‌دهند.","Python-Tutorial: Funktionen definieren":"آموزش پایتون: تعریف تابع‌ها","Projekt: Zahlenraten":"پروژه: حدس زدن عدد","Du verbindest Eingabe, Schleife und Entscheidungen zu einem kleinen Spiel.":"ورودی، حلقه و تصمیم‌ها را در یک بازی کوچک به هم وصل می‌کنید.","Jetzt setzt du alles Gelernte zusammen und baust ein echtes kleines Spiel.":"حالا همهٔ آنچه را یاد گرفته‌اید کنار هم می‌گذارید و یک بازی کوچک واقعی می‌سازید.","Der Plan":"نقشه","Das Programm kennt eine geheime Zahl. Der Spieler rät, und das Programm sagt „zu groß“ oder „zu klein“. Erst bei der richtigen Zahl endet das Spiel.":"برنامه یک عدد پنهان را می‌داند. بازیکن حدس می‌زند و برنامه می‌گوید «خیلی بزرگ» یا «خیلی کوچک». بازی فقط با عدد درست تمام می‌شود.","Hier steht die geheime Zahl fest, damit die Prüfung immer gleich ausfällt. Später kannst du sie mit dem Modul random zufällig wählen.":"اینجا عدد پنهان ثابت است تا بررسی همیشه یکسان باشد. بعداً می‌توانید آن را با ماژول random به‌طور تصادفی انتخاب کنید.","Die Spielschleife":"حلقهٔ بازی","Eine while-Schleife läuft, solange der Tipp falsch ist. In jeder Runde fragt sie neu. Ein Zähler merkt sich die Anzahl der Versuche.":"یک حلقهٔ while تا وقتی اجرا می‌شود که حدس اشتباه باشد. در هر دور دوباره می‌پرسد. یک شمارنده تعداد تلاش‌ها را به یاد می‌سپارد.","`!=` bedeutet „ungleich“. Bei Gleichheit endet die Schleife.":"`!=` یعنی «نابرابر». در صورت برابری حلقه تمام می‌شود.","Hinweise geben":"راهنمایی دادن","Innerhalb der Schleife entscheidest du mit if, ob der Tipp zu groß oder zu klein war. Am Ende gratuliert das Programm mit der Anzahl der Versuche. Teste das Spiel mit verschiedenen Eingabezeilen.":"داخل حلقه با if تصمیم می‌گیرید که حدس خیلی بزرگ بود یا خیلی کوچک. در آخر برنامه با تعداد تلاش‌ها تبریک می‌گوید. بازی را با خط‌های ورودی مختلف آزمایش کنید.","Diese Prüfung gehört in die Schleife, bevor neu gefragt wird.":"این بررسی داخل حلقه و پیش از پرسیدن دوباره می‌آید.","Das Spiel erweitern":"گسترش بازی","Wenn das Grundspiel läuft, kannst du es Schritt für Schritt verbessern. Begrenze zum Beispiel die Anzahl der Versuche oder frage am Ende, ob noch eine Runde gespielt werden soll. Ändere immer nur eine Sache und teste danach sofort. So findest du Fehler schnell, weil du weißt, was sich zuletzt geändert hat. Spiele dein Spiel anschließend selbst ein paar Runden und frage dich, was noch Spaß machen würde.":"وقتی بازی پایه کار کند، می‌توانید آن را قدم به قدم بهتر کنید. مثلاً تعداد تلاش‌ها را محدود کنید یا در آخر بپرسید که آیا یک دور دیگر بازی شود. همیشه فقط یک چیز را تغییر دهید و بلافاصله بعد از آن آزمایش کنید. به این ترتیب خطاها را زود پیدا می‌کنید، چون می‌دانید آخرین تغییر چه بوده است. بعد خودتان چند دور بازی کنید و از خود بپرسید که چه چیز دیگری می‌تواند جالب باشد.","Mit random wird jede Runde eine neue Zahl gewählt.":"با random در هر دور یک عدد تازه انتخاب می‌شود.","Neue Eingabe vergessen":"فراموش کردن ورودی تازه","Wird `tipp` in der Schleife nicht neu gelesen, entsteht eine Endlosschleife. Frage in jeder Runde neu.":"اگر `tipp` داخل حلقه دوباره خوانده نشود، یک حلقهٔ بی‌پایان ساخته می‌شود. در هر دور دوباره بپرسید.","Vergleich mit Text":"مقایسه با متن","Ohne `int()` vergleichst du Text mit einer Zahl und das Spiel endet nie. Wandle jede Eingabe um.":"بدون `int()` متن را با یک عدد مقایسه می‌کنید و بازی هرگز تمام نمی‌شود. هر ورودی را تبدیل کنید.","Baue das Spiel fertig: Es gibt Hinweise „Zu groß“ oder „Zu klein“ und schreibt am Ende „Richtig nach 3 Versuchen!“. Im Eingabefeld stehen die Tipps 10, 3 und 7.":"بازی را کامل کنید: راهنمایی „Zu groß“ یا „Zu klein“ می‌دهد و در آخر „Richtig nach 3 Versuchen!“ را می‌نویسد. در خانهٔ ورودی حدس‌های 10، 3 و 7 نوشته شده‌اند.","Lies den ersten Tipp vor der Schleife. In der Schleife: Hinweis ausgeben, neu fragen, versuche erhöhen.":"حدس اول را پیش از حلقه بخوانید. داخل حلقه: راهنمایی نشان دهید، دوباره بپرسید، versuche را بالا ببرید.","Du benutzt eine while-Schleife":"از یک حلقهٔ while استفاده می‌کنید","Du vergleichst mit != oder ==":"با != یا == مقایسه می‌کنید","Du zählst Versuche":"تلاش‌ها را می‌شمارید","Was bedeutet `!=`?":"`!=` چه معنایی دارد؟","gleich":"برابر","ungleich":"نابرابر","größer gleich":"بزرگ‌تر یا برابر","!= ist wahr, wenn zwei Werte verschieden sind.":"!= وقتی درست است که دو مقدار با هم فرق داشته باشند.","Warum wird der erste Tipp vor der Schleife gelesen?":"چرا حدس اول پیش از حلقه خوانده می‌شود؟","Weil Python sonst langsamer ist":"چون در غیر آن پایتون کندتر است","Das ist unnötig":"این کار لازم نیست","Damit die Bedingung schon einen Wert prüfen kann":"تا شرط از همان اول یک مقدار برای بررسی داشته باشد","Die while-Bedingung braucht einen Tipp zum Vergleichen.":"شرط while برای مقایسه به یک حدس نیاز دارد.","Wie wählt man später eine Zufallszahl?":"بعداً یک عدد تصادفی را چطور انتخاب می‌کنند؟","Mit dem Modul random":"با ماژول random","Mit print":"با print","Mit range allein":"فقط با range","`random.randint(1, 10)` liefert eine Zufallszahl.":"`random.randint(1, 10)` یک عدد تصادفی می‌دهد.","Ein Spiel besteht aus Zustand, Schleife und Regeln.":"یک بازی از وضعیت، حلقه و قاعده‌ها ساخته می‌شود.","Teste Programme mit verschiedenen Eingaben, nicht nur mit der richtigen.":"برنامه‌ها را با ورودی‌های مختلف آزمایش کنید، نه فقط با ورودی درست.","Python-Doku: Modul random":"مستندات پایتون: ماژول random","Ein Programm ist eine genaue Liste von Anweisungen. Der Computer versteht eigentlich nur Maschinencode aus Nullen und Einsen. Python ist eine sogenannte Hochsprache: Ein Hilfsprogramm, der Interpreter, liest deinen Text und übersetzt ihn Schritt für Schritt in Befehle, die der Prozessor ausführen kann.":"یک برنامه فهرست دقیقی از دستورها است. کمپیوتر در اصل فقط کد ماشین از صفر و یک را می‌فهمد. پایتون یک زبان سطح بالا است: یک برنامهٔ کمکی به نام مفسر (Interpreter) متن شما را می‌خواند و قدم به قدم به دستورهایی ترجمه می‌کند که پردازنده می‌تواند اجرا کند.","`print` ist eine eingebaute Funktion. Funktionen erkennst du an den runden Klammern dahinter. Was in den Klammern steht, nennt man Argument. Text muss in Anführungszeichen stehen, damit Python weiß: Das ist kein Befehl, sondern ein Stück Text, ein sogenannter String.":"`print` یک تابع داخلی است. تابع‌ها را از پرانتزهای گردِ بعد از نامشان می‌شناسید. آنچه داخل پرانتز است، آرگومان نامیده می‌شود. متن باید داخل علامت نقل‌قول باشد تا پایتون بداند: این دستور نیست، بلکه یک تکه متن است که به آن رشته (String) می‌گویند.","Diese feste Reihenfolge nennt man sequenzielle Ausführung. Python beginnt immer in der ersten Zeile und arbeitet sich nach unten vor. Es springt nicht von selbst zurück und überspringt nichts – erst später lernst du Werkzeuge wie `if` und Schleifen, die diesen Ablauf gezielt verändern.":"این ترتیب ثابت را اجرای ترتیبی می‌نامند. پایتون همیشه از خط اول شروع می‌کند و به پایین پیش می‌رود. خودش به عقب برنمی‌گردد و چیزی را جا نمی‌اندازد – بعداً ابزارهایی مثل `if` و حلقه‌ها را یاد می‌گیرید که این روند را عمداً تغییر می‌دهند.","Jede `print`-Anweisung beendet ihre Ausgabe mit einem Zeilenumbruch. Darum steht jeder Text in einer eigenen Zeile. Eine gute Übung: Stell dir vor, du bist der Computer, und spiele das Programm Zeile für Zeile im Kopf durch, bevor du es ausführst.":"هر دستور `print` خروجی خود را با رفتن به خط بعد تمام می‌کند. به همین دلیل هر متن در یک خط جدا می‌آید. یک تمرین خوب: فرض کنید خودتان کمپیوتر هستید و پیش از اجرا، برنامه را خط به خط در ذهن مرور کنید.","Kommentare sind nur für Menschen da. Der Interpreter entfernt sie, bevor er das Programm ausführt; sie machen es also weder langsamer noch schneller. Gute Kommentare erklären, warum etwas passiert, nicht was – das Was zeigt der Code selbst.":"توضیح‌ها (Comment) فقط برای انسان‌ها هستند. مفسر پیش از اجرای برنامه آن‌ها را حذف می‌کند؛ پس برنامه را نه کندتر می‌کنند و نه سریع‌تر. توضیح خوب می‌گوید چرا کاری انجام می‌شود، نه اینکه چه کاری – «چه» را خود کد نشان می‌دهد.","Kommentare helfen auch beim Testen: Setzt du eine Raute vor eine Zeile, wird sie vorübergehend abgeschaltet. Programmierer nennen das „auskommentieren“. So kannst du ausprobieren, wie sich das Programm ohne diese Zeile verhält, ohne sie zu löschen.":"توضیح‌ها در آزمایش هم کمک می‌کنند: اگر پیش از یک خط علامت # بگذارید، آن خط موقتاً خاموش می‌شود. برنامه‌نویسان به این کار «کامنت کردن» می‌گویند. به این ترتیب می‌توانید ببینید برنامه بدون آن خط چه رفتاری دارد، بدون اینکه آن را پاک کنید.","Fehler gehören zum Programmieren dazu, auch Profis sehen sie täglich. Ein `SyntaxError` bedeutet: Python versteht die Schreibweise nicht, ähnlich wie ein Satz ohne Verb. Das Programm startet dann gar nicht. Andere Fehler, zum Beispiel ein `NameError`, entstehen erst während des Laufs.":"خطاها بخشی از برنامه‌نویسی هستند؛ متخصصان هم هر روز آن‌ها را می‌بینند. `SyntaxError` یعنی پایتون نوشتار را نمی‌فهمد، مثل جمله‌ای بدون فعل. در این حالت برنامه اصلاً شروع نمی‌شود. خطاهای دیگر، مثلاً `NameError`، در وقت اجرا پیش می‌آیند.","Eine Fehlermeldung, auch Traceback genannt, zeigt die Datei, die Zeilennummer und am Ende den Fehlertyp mit einer kurzen Beschreibung. Manchmal liegt die eigentliche Ursache eine Zeile darüber, etwa wenn dort eine Klammer nicht geschlossen wurde. Ändere immer nur eine Sache und starte dann erneut.":"یک پیام خطا که Traceback هم نامیده می‌شود، فایل، شمارهٔ خط و در آخر نوع خطا را با توضیحی کوتاه نشان می‌دهد. گاهی علت اصلی یک خط بالاتر است، مثلاً وقتی آنجا یک پرانتز بسته نشده است. هر بار فقط یک چیز را تغییر دهید و دوباره اجرا کنید.","Genauer gesagt ist ein Variablenname in Python ein Etikett, das auf einen Wert im Arbeitsspeicher zeigt. Bei `alter = 25` erzeugt Python das Zahlenobjekt 25 und klebt das Etikett `alter` daran. Das Gleichheitszeichen bedeutet also „weise zu“, nicht „ist gleich“ wie in der Mathematik.":"دقیق‌تر بگوییم، نام متغیر در پایتون برچسبی است که به یک مقدار در حافظه اشاره می‌کند. با `alter = 25` پایتون عدد 25 را می‌سازد و برچسب `alter` را به آن می‌چسباند. پس علامت مساوی یعنی «اختصاص بده»، نه «برابر است» مثل ریاضی.","Jeder Wert hat einen Datentyp. `25` ist ein `int` (ganze Zahl), `\"Leyla\"` ist ein `str` (Text). Mit `type(alter)` kannst du den Typ jederzeit abfragen. Variablennamen dürfen Buchstaben, Ziffern und Unterstriche enthalten, aber nicht mit einer Ziffer beginnen. Groß- und Kleinschreibung zählt: `Alter` und `alter` sind zwei verschiedene Variablen.":"هر مقدار یک نوع داده دارد. `25` یک `int` (عدد صحیح) است و `\"Leyla\"` یک `str` (متن). با `type(alter)` می‌توانید هر وقت نوع را بپرسید. نام متغیر می‌تواند حرف، عدد و زیرخط داشته باشد، اما نباید با عدد شروع شود. حروف بزرگ و کوچک فرق دارند: `Alter` و `alter` دو متغیر جدا هستند.","Python rechnet nach den Regeln, die du aus der Schule kennst: Punkt vor Strich, Klammern zuerst. Zusätzlich gibt es `**` für Potenzen (`2 ** 3` ergibt 8), `//` für die ganzzahlige Division (`7 // 2` ergibt 3) und `%` für den Rest einer Division (`7 % 2` ergibt 1).":"پایتون با قاعده‌هایی حساب می‌کند که از مکتب می‌شناسید: ضرب و تقسیم پیش از جمع و تفریق، و پرانتز اول. علاوه بر آن `**` برای توان است (`2 ** 3` می‌شود 8)، `//` برای تقسیم صحیح (`7 // 2` می‌شود 3) و `%` برای باقی‌ماندهٔ تقسیم (`7 % 2` می‌شود 1).","Wichtig: Der normale Schrägstrich `/` liefert immer eine Kommazahl vom Typ `float`, auch bei `6 / 3` (Ergebnis `2.0`). Kommazahlen werden im Computer binär gespeichert und sind deshalb manchmal minimal ungenau: `0.1 + 0.2` ergibt `0.30000000000000004`. Für Geldbeträge rundet man deshalb mit `round(wert, 2)`.":"مهم: خط مورب عادی `/` همیشه یک عدد اعشاری از نوع `float` می‌دهد، حتی در `6 / 3` (نتیجه `2.0`). اعداد اعشاری در کمپیوتر به شکل دودویی ذخیره می‌شوند و به همین دلیل گاهی کمی نادقیق‌اند: `0.1 + 0.2` می‌شود `0.30000000000000004`. برای مبلغ پول به همین دلیل با `round(wert, 2)` گرد می‌کنند.","f-Strings gibt es seit Python 3.6 und sie sind heute die übliche Art, Texte zusammenzusetzen. In den geschweiften Klammern darf sogar ein ganzer Ausdruck stehen, etwa `{stunden * 5}`. Python rechnet ihn aus und setzt das Ergebnis als Text ein.":"f-String ها از پایتون 3.6 وجود دارند و امروز روش معمول ساختن متن هستند. داخل آکولادها حتی می‌توان یک عبارت کامل نوشت، مثلاً `{stunden * 5}`. پایتون آن را حساب می‌کند و نتیجه را به شکل متن جایگزین می‌کند.","Du kannst die Darstellung auch formatieren: `{preis:.2f}` zeigt eine Zahl mit genau zwei Nachkommastellen. Ohne f-String müsstest du Zahlen erst mit `str()` in Text umwandeln und mit `+` aneinanderhängen – das ist länger und fehleranfälliger.":"می‌توانید نمایش را هم قالب‌بندی کنید: `{preis:.2f}` عدد را با دقیقاً دو رقم اعشار نشان می‌دهد. بدون f-String باید اعداد را اول با `str()` به متن تبدیل کنید و با `+` به هم وصل کنید – این طولانی‌تر است و خطای بیشتری دارد.","Bei `kontostand = kontostand - 30` rechnet Python immer zuerst die rechte Seite aus: Es nimmt den aktuellen Wert 100, zieht 30 ab und erhält 70. Erst danach wird das Etikett `kontostand` auf das neue Ergebnis umgehängt. Der alte Wert ist danach nicht mehr über diesen Namen erreichbar.":"در `kontostand = kontostand - 30` پایتون همیشه اول سمت راست را حساب می‌کند: مقدار فعلی 100 را می‌گیرد، 30 را کم می‌کند و 70 به دست می‌آورد. فقط بعد از آن برچسب `kontostand` به نتیجهٔ تازه منتقل می‌شود. مقدار قبلی دیگر با این نام قابل دسترس نیست.","Die Kurzformen `+=`, `-=`, `*=` und `/=` heißen erweiterte Zuweisungen. Sie sparen Schreibarbeit und machen die Absicht deutlich: Ein vorhandener Wert wird verändert. Die Variable muss dafür vorher schon einen Wert haben, sonst meldet Python einen `NameError`.":"شکل‌های کوتاه `+=`، `-=`، `*=` و `/=` را اختصاص افزایشی می‌نامند. نوشتن را کم می‌کنند و هدف را روشن می‌کنند: یک مقدار موجود تغییر می‌کند. برای این کار متغیر باید از قبل مقدار داشته باشد، وگرنه پایتون `NameError` می‌دهد.","`input()` hält das Programm an und wartet, bis die Eingabe mit Enter bestätigt wird. Erst dann geht es mit der nächsten Zeile weiter. Der Text in den Klammern heißt Eingabeaufforderung (Prompt); ein Leerzeichen am Ende sorgt dafür, dass die Antwort nicht direkt am Fragezeichen klebt.":"`input()` برنامه را نگه می‌دارد و منتظر می‌ماند تا ورودی با Enter تأیید شود. فقط بعد از آن خط بعدی اجرا می‌شود. متن داخل پرانتز را درخواست ورودی (Prompt) می‌نامند؛ یک فاصله در آخر آن باعث می‌شود جواب درست به علامت سوال نچسبد.","Programme mit Eingaben nennt man interaktiv. Hier in der Akademie trägst du die Eingaben vorher in das Feld „Eingaben für das Programm“ ein, eine pro Zeile. Python liest sie der Reihe nach, so als hätte jemand sie getippt.":"برنامه‌هایی را که ورودی می‌گیرند، تعاملی می‌نامند. اینجا در آکادمی ورودی‌ها را از قبل در خانهٔ «ورودی‌ها برای برنامه» می‌نویسید، هر کدام در یک خط. پایتون آن‌ها را به ترتیب می‌خواند، انگار کسی آن‌ها را تایپ کرده است.","Der Grund: Eine Tastatur liefert nur Zeichen. Ob „42“ eine Zahl, eine Hausnummer oder ein Teil eines Passworts ist, kann Python nicht wissen. Deshalb gibt `input()` immer einen `str` zurück, und du entscheidest, wie er verwendet wird. Diese Umwandlung von einem Typ in einen anderen heißt Typumwandlung oder Casting.":"دلیلش این است: کیبورد فقط نویسه می‌دهد. پایتون نمی‌تواند بداند «42» یک عدد است، یک شمارهٔ خانه یا بخشی از یک رمز. به همین دلیل `input()` همیشه یک `str` برمی‌گرداند و شما تصمیم می‌گیرید چطور از آن استفاده شود. این تبدیل یک نوع به نوع دیگر را تبدیل نوع یا Casting می‌نامند.","Gibt jemand bei `int()` etwas ein, das keine ganze Zahl ist, etwa „zwölf“ oder „3.5“, bricht das Programm mit einem `ValueError` ab. Später lernst du mit `try` und `except`, solche Fehler abzufangen. Bis dahin hilft eine klare Frage, die sagt, was eingegeben werden soll.":"اگر کسی در `int()` چیزی بنویسد که عدد صحیح نیست، مثلاً «دوازده» یا «3.5»، برنامه با `ValueError` متوقف می‌شود. بعداً با `try` و `except` یاد می‌گیرید چنین خطاهایی را بگیرید. تا آن وقت یک سوال روشن که بگوید چه باید نوشته شود کمک می‌کند.","Jeder Aufruf von `input()` liest genau eine Zeile. Die erste Eingabe landet also in `a`, die zweite in `b`. Fehlt eine Zeile, meldet Python einen `EOFError` – das heißt „Ende der Eingabe erreicht“, weil keine Antwort mehr vorhanden war.":"هر بار صدا زدن `input()` دقیقاً یک خط را می‌خواند. پس ورودی اول در `a` و ورودی دوم در `b` قرار می‌گیرد. اگر یک خط کم باشد، پایتون `EOFError` می‌دهد – یعنی «به پایان ورودی رسیدیم»، چون جواب دیگری نبود.","Du kannst Umwandlung und Eingabe in einer Zeile verschachteln, wie in `int(input(...))`. Python arbeitet dann von innen nach außen: Zuerst wird gefragt, dann wird die Antwort umgewandelt. Diese Verschachtelung von Funktionen ist in der Programmierung sehr häufig.":"می‌توانید تبدیل و ورودی را در یک خط تودرتو بنویسید، مثل `int(input(...))`. پایتون از داخل به بیرون کار می‌کند: اول سوال پرسیده می‌شود، بعد جواب تبدیل می‌شود. این تودرتو کردن تابع‌ها در برنامه‌نویسی بسیار رایج است.","Der Punkt als Dezimaltrenner stammt aus dem Englischen, und fast alle Programmiersprachen verwenden ihn. Für eine Eingabe mit Komma kannst du den Text vorher ersetzen: `float(text.replace(\",\", \".\"))`. Damit funktionieren beide Schreibweisen.":"نقطه به عنوان جداکنندهٔ اعشار از انگلیسی آمده و تقریباً همهٔ زبان‌های برنامه‌نویسی از آن استفاده می‌کنند. برای ورودی با ویرگول می‌توانید متن را پیش از تبدیل جایگزین کنید: `float(text.replace(\",\", \".\"))`. با این کار هر دو شیوهٔ نوشتن کار می‌کنند.","`float` steht für Gleitkommazahl (floating point). Solche Zahlen können sehr groß oder sehr klein sein, haben aber nur etwa 15 bis 16 gültige Stellen. Für Alltagsrechnungen reicht das völlig; bei Ergebnissen mit vielen Nachkommastellen hilft `round()` beim Anzeigen.":"`float` به معنای عدد ممیز شناور (floating point) است. چنین اعدادی می‌توانند بسیار بزرگ یا بسیار کوچک باشند، اما فقط حدود 15 تا 16 رقم معتبر دارند. برای حساب‌های روزمره کاملاً کافی است؛ برای نتیجه‌هایی با رقم‌های اعشار زیاد، `round()` در نمایش کمک می‌کند.","Eine Bedingung ist ein Ausdruck, der entweder `True` (wahr) oder `False` (falsch) ergibt. Diese beiden Werte haben den Datentyp `bool`, benannt nach dem Mathematiker George Boole. Vergleiche wie `>`, `<`, `>=`, `<=`, `==` (gleich) und `!=` (ungleich) liefern immer einen solchen Wahrheitswert.":"یک شرط عبارتی است که یا `True` (درست) یا `False` (نادرست) می‌شود. این دو مقدار نوع داده‌ای `bool` دارند که از نام ریاضی‌دان جورج بول گرفته شده است. مقایسه‌هایی مثل `>`، `<`، `>=`، `<=`، `==` (برابر) و `!=` (نابرابر) همیشه چنین مقدار درست یا نادرستی می‌دهند.","Der Doppelpunkt am Ende der if-Zeile ist Pflicht. Er sagt: Jetzt folgt ein Block. In vielen anderen Sprachen markieren geschweifte Klammern solche Blöcke; Python nutzt stattdessen die Einrückung. Darum ist sie hier keine Formsache, sondern Teil der Sprache.":"دونقطه در آخر خط if اجباری است. می‌گوید: حالا یک بلوک می‌آید. در بسیاری از زبان‌های دیگر آکولادها چنین بلوک‌هایی را مشخص می‌کنند؛ پایتون به جای آن از تورفتگی استفاده می‌کند. پس تورفتگی اینجا فقط ظاهر نیست، بلکه بخشی از زبان است.","Python prüft die Zweige von oben nach unten. Sobald eine Bedingung wahr ist, wird ihr Block ausgeführt und alle restlichen `elif`- und `else`-Zweige werden übersprungen. Deshalb ist die Reihenfolge wichtig: Die speziellste Bedingung gehört nach oben.":"پایتون شاخه‌ها را از بالا به پایین بررسی می‌کند. همین که یک شرط درست باشد، بلوک آن اجرا می‌شود و همهٔ شاخه‌های `elif` و `else` باقی‌مانده رد می‌شوند. به همین دلیل ترتیب مهم است: خاص‌ترین شرط باید بالا باشد.","Achte auf den Unterschied zwischen `=` und `==`. Ein einfaches Gleichheitszeichen weist einen Wert zu, das doppelte vergleicht zwei Werte. `if note = 1:` ist deshalb ein Syntaxfehler. `else` hat nie eine eigene Bedingung; es fängt alles auf, was vorher nicht gepasst hat.":"به فرق بین `=` و `==` توجه کنید. یک علامت مساوی مقدار اختصاص می‌دهد، دو علامت دو مقدار را مقایسه می‌کند. به همین دلیل `if note = 1:` خطای نوشتاری است. `else` هیچ‌وقت شرط خودش را ندارد؛ هر چیزی را می‌گیرد که قبلاً جور نشده است.","`and`, `or` und `not` heißen logische Operatoren. Python wertet sie sparsam aus: Ist bei `and` der linke Teil schon falsch, wird der rechte gar nicht mehr geprüft, weil das Ergebnis feststeht. Bei `or` genügt ein wahrer linker Teil. Das nennt man Kurzschlussauswertung.":"`and`، `or` و `not` را عملگرهای منطقی می‌نامند. پایتون آن‌ها را صرفه‌جویانه بررسی می‌کند: اگر در `and` بخش چپ نادرست باشد، بخش راست اصلاً بررسی نمی‌شود، چون نتیجه معلوم است. در `or` یک بخش چپ درست کافی است. به این ارزیابی کوتاه‌مدار می‌گویند.","Wenn du `and` und `or` mischst, bindet `and` stärker – ähnlich wie Punkt vor Strich. Setze bei gemischten Bedingungen lieber Klammern, zum Beispiel `(alter >= 16 or mit_eltern) and ticket`. Das macht die Regel für dich und andere sofort lesbar.":"اگر `and` و `or` را با هم به کار ببرید، `and` قوی‌تر می‌بندد – شبیه ضرب پیش از جمع. در شرط‌های مخلوط بهتر است پرانتز بگذارید، مثلاً `(alter >= 16 or mit_eltern) and ticket`. این کار قاعده را برای خودتان و دیگران فوراً خوانا می‌کند.","Dieses Vorgehen nennt man Pseudocode: Man beschreibt den Ablauf zuerst in normaler Sprache und übersetzt ihn dann in Code. So trennst du das Nachdenken über die Logik vom Kampf mit der Schreibweise. Auch in Informatikstudiengängen wird so gearbeitet.":"این روش را شبه‌کد (Pseudocode) می‌نامند: اول روند را با زبان عادی توصیف می‌کنند و بعد آن را به کد ترجمه می‌کنند. به این ترتیب فکر کردن دربارهٔ منطق را از درگیری با شیوهٔ نوشتن جدا می‌کنید. در رشته‌های علوم کمپیوتر دانشگاه هم همین طور کار می‌شود.","Teste jede Bedingung mit Grenzwerten. Bei „ab 50 Euro Rabatt“ probierst du 49, 50 und 51. Gerade an der Grenze passieren die meisten Fehler, etwa wenn `>` statt `>=` geschrieben wurde. Diese Technik heißt Grenzwertanalyse und ist ein Grundwerkzeug beim Testen.":"هر شرط را با مقدارهای مرزی آزمایش کنید. در «تخفیف از 50 یورو» عدد 49، 50 و 51 را امتحان می‌کنید. بیشتر خطاها درست در مرز پیش می‌آیند، مثلاً وقتی به جای `>=` نوشته شده `>`. این روش تحلیل مقدار مرزی نام دارد و ابزار پایه‌ای آزمایش است.","In jeder Runde bekommt die Schleifenvariable – hier `i` – den nächsten Wert der Reihe. Der eingerückte Block wird dann mit genau diesem Wert ausgeführt. Nach dem letzten Wert endet die Schleife, und Python macht mit der ersten nicht eingerückten Zeile darunter weiter.":"در هر دور، متغیر حلقه – اینجا `i` – مقدار بعدی رشته را می‌گیرد. بعد بلوک تورفته با همین مقدار اجرا می‌شود. بعد از آخرین مقدار حلقه تمام می‌شود و پایتون با اولین خط بدون تورفتگی زیر آن ادامه می‌دهد.","Dass `range` bei 0 beginnt, ist in der Informatik üblich und passt zu den Positionen in Listen, die ebenfalls bei 0 starten. `range(5)` erzeugt die Zahlen nicht alle auf einmal im Speicher, sondern liefert sie nacheinander. Darum funktioniert auch `range(1000000)` ohne Probleme.":"اینکه `range` از 0 شروع می‌شود در علوم کمپیوتر معمول است و با جایگاه‌ها در لیست‌ها جور است که آن‌ها هم از 0 شروع می‌شوند. `range(5)` همهٔ اعداد را یک‌جا در حافظه نمی‌سازد، بلکه آن‌ها را یکی پس از دیگری می‌دهد. به همین دلیل `range(1000000)` هم بدون مشکل کار می‌کند.","Die Regel „Start inklusive, Ende exklusive“ wirkt zuerst seltsam, hat aber Vorteile: `range(0, 10)` enthält genau 10 Zahlen, und `range(0, 5)` und `range(5, 10)` schließen lückenlos aneinander an. Diese Konvention findest du in Python überall, zum Beispiel auch beim Ausschneiden von Listen.":"قاعدهٔ «شروع شامل، پایان غیرشامل» اول عجیب به نظر می‌رسد، اما فایده دارد: `range(0, 10)` دقیقاً 10 عدد دارد، و `range(0, 5)` و `range(5, 10)` بدون فاصله به هم وصل می‌شوند. این قرارداد را در پایتون همه‌جا می‌بینید، مثلاً در بریدن بخشی از لیست‌ها.","Die Schrittweite darf auch negativ sein: `range(10, 0, -1)` zählt rückwärts von 10 bis 1. Eine Schrittweite von 0 ist nicht erlaubt, weil die Schleife sonst nie vorankäme. Mit der Schleifenvariable kannst du rechnen, etwa `print(zahl * 3)` für die Dreierreihe.":"گام می‌تواند منفی هم باشد: `range(10, 0, -1)` از 10 تا 1 به عقب می‌شمارد. گام 0 مجاز نیست، چون حلقه هیچ‌وقت جلو نمی‌رفت. با متغیر حلقه می‌توانید حساب کنید، مثلاً `print(zahl * 3)` برای جدول ضرب سه.","Eine `for`-Schleife nimmst du, wenn die Anzahl der Runden vorher feststeht. `while` passt, wenn du nicht weißt, wie oft wiederholt werden muss – zum Beispiel, bis ein Nutzer das richtige Passwort eingibt. Die Bedingung wird vor jeder Runde neu geprüft.":"حلقهٔ `for` را وقتی به کار می‌برید که تعداد دورها از قبل معلوم است. `while` وقتی مناسب است که نمی‌دانید چند بار باید تکرار شود – مثلاً تا وقتی کاربر رمز درست را بنویسد. شرط پیش از هر دور دوباره بررسی می‌شود.","Wird die Bedingung nie falsch, entsteht eine Endlosschleife: Das Programm hängt. Hier in der Akademie bricht ein Zeitlimit den Lauf nach einiger Zeit ab. Frage dich bei jeder while-Schleife: Welche Zeile sorgt dafür, dass die Bedingung irgendwann falsch wird?":"اگر شرط هیچ‌وقت نادرست نشود، یک حلقهٔ بی‌پایان پیش می‌آید: برنامه گیر می‌کند. اینجا در آکادمی یک محدودیت زمانی اجرا را بعد از مدتی قطع می‌کند. در هر حلقهٔ while از خود بپرسید: کدام خط باعث می‌شود شرط بالاخره نادرست شود؟","Der Operator `%` liefert den Rest einer Division. `zahl % 7 == 0` bedeutet deshalb: Die Zahl ist ohne Rest durch 7 teilbar. Mit `zahl % 2 == 0` erkennst du gerade Zahlen. Dieser Trick taucht in sehr vielen Programmen auf.":"عملگر `%` باقی‌ماندهٔ تقسیم را می‌دهد. پس `zahl % 7 == 0` یعنی: عدد بدون باقی‌مانده بر 7 بخش‌پذیر است. با `zahl % 2 == 0` عددهای جفت را می‌شناسید. این ترفند در بسیاری از برنامه‌ها دیده می‌شود.","`break` beendet die gesamte Schleife sofort. Sein Gegenstück ist `continue`: Es bricht nur die aktuelle Runde ab und springt direkt zur nächsten. Beide Befehle sollten sparsam eingesetzt werden, weil sie den Ablauf schwerer lesbar machen können.":"`break` کل حلقه را فوراً تمام می‌کند. همتای آن `continue` است: فقط دور فعلی را قطع می‌کند و مستقیم به دور بعدی می‌رود. هر دو دستور را باید کم به کار برد، چون ممکن است روند برنامه را سخت‌خوان کنند.","Eine Liste ist eine geordnete Sammlung: Die Reihenfolge bleibt erhalten, und derselbe Wert darf mehrfach vorkommen. Eine Liste kann sogar Werte verschiedener Typen mischen, etwa `[\"Ali\", 34, True]`. In der Praxis enthält eine Liste aber meist gleichartige Dinge, zum Beispiel nur Namen oder nur Preise.":"لیست یک مجموعهٔ مرتب است: ترتیب حفظ می‌شود و یک مقدار می‌تواند چند بار بیاید. لیست حتی می‌تواند مقدارهایی از نوع‌های مختلف داشته باشد، مثلاً `[\"Ali\", 34, True]`. اما در عمل یک لیست بیشتر چیزهای هم‌نوع دارد، مثلاً فقط نام‌ها یا فقط قیمت‌ها.","`len()` funktioniert nicht nur bei Listen, sondern auch bei Texten: `len(\"Hallo\")` ergibt 5. Eine leere Liste schreibst du als `[]`; ihre Länge ist 0. Leere Listen sind praktisch, wenn du später nach und nach Werte sammeln willst.":"`len()` نه فقط برای لیست‌ها، بلکه برای متن‌ها هم کار می‌کند: `len(\"Hallo\")` می‌شود 5. لیست خالی را `[]` می‌نویسید؛ طول آن 0 است. لیست‌های خالی وقتی مفیدند که بخواهید بعداً کم‌کم مقدار جمع کنید.","Die Zählung ab 0 bedeutet: Der Index sagt, wie viele Schritte du vom Anfang gehen musst. Der erste Eintrag ist 0 Schritte entfernt. Mit negativen Zahlen zählst du vom Ende: `obst[-1]` ist immer der letzte Eintrag, egal wie lang die Liste ist.":"شمردن از 0 یعنی: اندیس می‌گوید چند قدم باید از اول بروید. اولین عنصر 0 قدم فاصله دارد. با عددهای منفی از آخر می‌شمارید: `obst[-1]` همیشه آخرین عنصر است، هر قدر لیست طولانی باشد.","Greifst du auf eine Position zu, die es nicht gibt, meldet Python einen `IndexError`. Listen sind veränderbar: `obst[0] = \"Birne\"` ersetzt den ersten Eintrag, `append()` verändert die Liste direkt. Mit `obst[0:2]` schneidest du einen Teil heraus – das nennt man Slicing.":"اگر به جایگاهی دسترسی بخواهید که وجود ندارد، پایتون `IndexError` می‌دهد. لیست‌ها قابل تغییرند: `obst[0] = \"Birne\"` عنصر اول را عوض می‌کند و `append()` خود لیست را تغییر می‌دهد. با `obst[0:2]` بخشی را جدا می‌کنید – به این کار Slicing می‌گویند.","Bei `for p in punkte:` bekommt `p` in jeder Runde den nächsten Eintrag der Liste. Du brauchst also keinen Zähler und keinen Index. Dieses Muster – alle Elemente einer Sammlung nacheinander bearbeiten – heißt Iteration und ist eines der wichtigsten Konzepte überhaupt.":"در `for p in punkte:` متغیر `p` در هر دور عنصر بعدی لیست را می‌گیرد. پس به شمارنده و اندیس نیاز ندارید. این الگو – پردازش همهٔ عناصر یک مجموعه یکی پس از دیگری – پیمایش (Iteration) نام دارد و یکی از مهم‌ترین مفهوم‌هاست.","Häufig sammelt man in einer Schleife ein Ergebnis: Man beginnt mit `summe = 0` und rechnet in jeder Runde `summe += p`. Genau das macht `sum()` intern. Wer dieses Muster versteht, kann auch Durchschnitt, Zählungen und Filter selbst bauen.":"اغلب در یک حلقه نتیجه‌ای جمع می‌شود: با `summe = 0` شروع می‌کنند و در هر دور `summe += p` حساب می‌کنند. `sum()` در داخل دقیقاً همین کار را می‌کند. هر کس این الگو را بفهمد، می‌تواند میانگین، شمارش و فیلتر را هم خودش بسازد.","`sorted()` lässt die ursprüngliche Liste unverändert und gibt eine neue zurück. Die Methode `noten.sort()` dagegen sortiert die Liste selbst und gibt nichts zurück. Mit `sorted(noten, reverse=True)` erhältst du absteigende Reihenfolge.":"`sorted()` لیست اصلی را تغییر نمی‌دهد و یک لیست تازه برمی‌گرداند. اما متد `noten.sort()` خود لیست را مرتب می‌کند و چیزی برنمی‌گرداند. با `sorted(noten, reverse=True)` ترتیب نزولی می‌گیرید.","Der Operator `in` durchsucht die Liste von vorne bis hinten. Bei kurzen Listen ist das sofort erledigt; bei Millionen Einträgen dauert es messbar länger. Texte werden alphabetisch sortiert, wobei Großbuchstaben vor Kleinbuchstaben kommen, weil der Computer die Zeichencodes vergleicht.":"عملگر `in` لیست را از اول تا آخر جستجو می‌کند. در لیست‌های کوتاه این کار فوری تمام می‌شود؛ در میلیون‌ها عنصر به‌طور قابل اندازه‌گیری بیشتر طول می‌کشد. متن‌ها به ترتیب الفبا مرتب می‌شوند و حروف بزرگ پیش از حروف کوچک می‌آیند، چون کمپیوتر کد نویسه‌ها را مقایسه می‌کند.","Mit `def` definierst du eine Funktion. Dabei wird ihr Code nur gespeichert, aber noch nicht ausgeführt. Erst der Aufruf `begruessen()` mit Klammern startet sie. Ohne Klammern sprichst du nur über die Funktion, ohne sie auszuführen.":"با `def` یک تابع تعریف می‌کنید. در این حالت کد آن فقط ذخیره می‌شود، اما هنوز اجرا نمی‌شود. فقط صدا زدن `begruessen()` با پرانتز آن را اجرا می‌کند. بدون پرانتز فقط دربارهٔ تابع حرف می‌زنید، بدون اینکه اجرایش کنید.","Programmierer sprechen vom DRY-Prinzip: „Don't Repeat Yourself“ – wiederhole dich nicht. Wenn du denselben Code an drei Stellen hast und ihn ändern musst, vergisst du leicht eine Stelle. Steht er in einer Funktion, änderst du ihn genau einmal.":"برنامه‌نویسان از اصل DRY حرف می‌زنند: «Don't Repeat Yourself» – خودت را تکرار نکن. اگر همان کد را در سه جا داشته باشید و باید تغییرش دهید، آسان یک جا را فراموش می‌کنید. اگر در یک تابع باشد، آن را دقیقاً یک بار تغییر می‌دهید.","Parameter sind die Namen in der Definition, Argumente die echten Werte beim Aufruf. Beim Aufruf `begruessen(\"Omid\")` wird `name` für diesen einen Durchlauf mit „Omid“ belegt. Eine Funktion kann mehrere Parameter haben, getrennt durch Kommas.":"پارامترها نام‌های داخل تعریف هستند و آرگومان‌ها مقدارهای واقعی در وقت صدا زدن. با `begruessen(\"Omid\")` متغیر `name` برای همین یک اجرا مقدار «Omid» را می‌گیرد. یک تابع می‌تواند چند پارامتر داشته باشد که با ویرگول جدا می‌شوند.","Variablen, die in einer Funktion entstehen, sind lokal: Sie existieren nur während des Aufrufs und sind außerhalb unsichtbar. Das schützt vor Verwechslungen, denn zwei Funktionen dürfen dieselben Namen benutzen, ohne sich zu stören. Diesen Sichtbarkeitsbereich nennt man Scope.":"متغیرهایی که داخل تابع ساخته می‌شوند محلی هستند: فقط در وقت اجرای تابع وجود دارند و بیرون از آن دیده نمی‌شوند. این از اشتباه جلوگیری می‌کند، چون دو تابع می‌توانند نام‌های یکسان داشته باشند، بدون اینکه مزاحم هم شوند. این محدودهٔ دید را Scope می‌نامند.","`return` beendet die Funktion sofort und liefert den Wert an die Stelle des Aufrufs zurück. Der Aufruf `brutto(100)` verhält sich danach wie der Wert `119.0`. Du kannst ihn ausgeben, in einer Variable speichern oder in eine weitere Rechnung einsetzen.":"`return` تابع را فوراً تمام می‌کند و مقدار را به جای صدا زدن برمی‌گرداند. بعد از آن `brutto(100)` مثل مقدار `119.0` رفتار می‌کند. می‌توانید آن را نمایش دهید، در یک متغیر ذخیره کنید یا در حساب دیگری به کار ببرید.","Eine Funktion ohne `return` gibt automatisch den besonderen Wert `None` zurück, was „nichts“ bedeutet. Der Unterschied zu `print` ist wichtig: `print` zeigt nur etwas auf dem Bildschirm, das Programm kann mit der Anzeige aber nicht weiterrechnen. `return` übergibt den Wert tatsächlich.":"تابعی که `return` ندارد خودکار مقدار ویژهٔ `None` را برمی‌گرداند که یعنی «هیچ». فرق آن با `print` مهم است: `print` فقط چیزی را روی صفحه نشان می‌دهد و برنامه نمی‌تواند با آن نمایش حساب کند. `return` مقدار را واقعاً تحویل می‌دهد.","Beim Aufruf kannst du Argumente auch mit Namen übergeben, etwa `gruss(\"Nora\", sprache=\"en\")`. Solche Schlüsselwortargumente machen Aufrufe besser lesbar, weil man sofort sieht, welcher Wert wofür steht. Ihre Reihenfolge ist dann egal.":"در وقت صدا زدن می‌توانید آرگومان‌ها را با نام هم بدهید، مثلاً `gruss(\"Nora\", sprache=\"en\")`. این آرگومان‌های کلیدی صدا زدن را خواناتر می‌کنند، چون فوراً دیده می‌شود کدام مقدار برای چیست. ترتیبشان در این حالت مهم نیست.","Du kennst Standardwerte schon von eingebauten Funktionen: `print` hat zum Beispiel den Parameter `end`, der standardmäßig ein Zeilenumbruch ist. Mit `print(\"Hallo\", end=\" \")` bleibt die nächste Ausgabe in derselben Zeile. Gute Funktionen haben sinnvolle Standardwerte für den häufigsten Fall.":"مقدار پیش‌فرض را از تابع‌های داخلی هم می‌شناسید: `print` مثلاً پارامتر `end` را دارد که به‌طور پیش‌فرض رفتن به خط بعد است. با `print(\"Hallo\", end=\" \")` خروجی بعدی در همان خط می‌ماند. تابع‌های خوب برای رایج‌ترین حالت مقدار پیش‌فرض معقول دارند.","Bevor man programmiert, zerlegt man ein Problem in kleine Teile: Zahl festlegen, Tipp einlesen, vergleichen, Hinweis geben, wiederholen. Diese Zerlegung nennt man Dekomposition. Jeder Teil ist für sich einfach und lässt sich einzeln testen.":"پیش از برنامه‌نویسی، مسئله را به بخش‌های کوچک تقسیم می‌کنند: تعیین عدد، خواندن حدس، مقایسه، دادن راهنمایی، تکرار. این تقسیم را تجزیه (Decomposition) می‌نامند. هر بخش به تنهایی ساده است و جداگانه آزمایش می‌شود.","Die geheime Zahl steht hier zunächst fest im Code. Das ist beim Entwickeln praktisch, weil du genau weißt, welcher Tipp richtig ist. Erst wenn das Spiel funktioniert, ersetzt du sie durch eine Zufallszahl.":"عدد مخفی اینجا اول ثابت در کد نوشته شده است. این در وقت ساختن مفید است، چون دقیقاً می‌دانید کدام حدس درست است. فقط وقتی بازی کار کرد، آن را با یک عدد تصادفی عوض می‌کنید.","Der erste Tipp wird vor der Schleife gelesen, damit die Bedingung `tipp != geheim` beim ersten Prüfen schon einen Wert hat. Dieses Muster – einmal vor der Schleife lesen, dann am Ende jeder Runde erneut – ist bei Eingabeschleifen sehr verbreitet.":"حدس اول پیش از حلقه خوانده می‌شود تا شرط `tipp != geheim` در اولین بررسی مقدار داشته باشد. این الگو – یک بار پیش از حلقه خواندن و بعد در آخر هر دور دوباره – در حلقه‌های ورودی بسیار رایج است.","Der Zähler `versuche` beginnt bei 1, weil der erste Tipp schon abgegeben wurde. Solche Kleinigkeiten nennt man Off-by-one-Fehler, wenn sie falsch sind: Das Ergebnis liegt dann genau um eins daneben. Spiele den Ablauf mit zwei, drei Tipps im Kopf durch und prüfe die Zahl.":"شمارندهٔ `versuche` از 1 شروع می‌شود، چون حدس اول از قبل داده شده است. اگر چنین جزئیاتی اشتباه باشند، به آن خطای یکی‌کم‌یا‌زیاد (Off-by-one) می‌گویند: نتیجه دقیقاً یکی کم یا زیاد است. روند را با دو یا سه حدس در ذهن مرور کنید و عدد را بررسی کنید.","Der Vergleich steht innerhalb der Schleife, also eingerückt. So bekommt der Spieler nach jedem falschen Tipp sofort einen Hinweis. Die Glückwunschnachricht steht dagegen nach der Schleife, denn sie soll nur einmal erscheinen, wenn die Schleife endet.":"مقایسه داخل حلقه است، یعنی تورفته. به این ترتیب بازیکن بعد از هر حدس اشتباه فوراً راهنمایی می‌گیرد. اما پیام تبریک بعد از حلقه است، چون باید فقط یک بار، وقتی حلقه تمام شد، بیاید.","Das Spiel ist ein Beispiel für binäre Suche: Wer klug rät, nimmt immer die Mitte des verbleibenden Bereichs. Bei Zahlen von 1 bis 100 reichen so höchstens sieben Versuche. Dieses Prinzip steckt auch in schnellen Suchverfahren, die Informatikstudierende früh kennenlernen.":"این بازی نمونه‌ای از جستجوی دودویی است: کسی که هوشمندانه حدس بزند همیشه وسط محدودهٔ باقی‌مانده را انتخاب می‌کند. برای عددهای 1 تا 100 به این شکل حداکثر هفت تلاش کافی است. این اصل در روش‌های جستجوی سریع هم هست که دانشجویان علوم کمپیوتر زود با آن آشنا می‌شوند.","`import random` lädt ein Modul aus der Standardbibliothek. Module sind Sammlungen fertiger Funktionen, die mit Python mitgeliefert werden. `random.randint(1, 20)` liefert eine zufällige ganze Zahl von 1 bis 20 – hier sind, anders als bei `range`, beide Grenzen enthalten.":"`import random` یک ماژول از کتابخانهٔ استاندارد را بار می‌کند. ماژول‌ها مجموعه‌ای از تابع‌های آماده‌اند که همراه پایتون می‌آیند. `random.randint(1, 20)` یک عدد صحیح تصادفی از 1 تا 20 می‌دهد – اینجا برخلاف `range` هر دو مرز شامل هستند.","Kleine, getestete Schritte sind die wichtigste Arbeitsweise beim Programmieren. Wenn nach einer Änderung etwas nicht mehr funktioniert, weißt du genau, wo du suchen musst. Profis sichern funktionierende Zwischenstände zusätzlich mit Versionsverwaltung wie Git.":"قدم‌های کوچک و آزمایش‌شده مهم‌ترین روش کار در برنامه‌نویسی است. اگر بعد از یک تغییر چیزی دیگر کار نکند، دقیقاً می‌دانید کجا را باید بگردید. متخصصان وضعیت‌های سالم میانی را علاوه بر آن با سیستم کنترل نسخه مثل Git ذخیره می‌کنند."};})(typeof window!=="undefined"?window:globalThis);
